<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_super_admin();$invoice=trim($_GET['invoice']??$_POST['invoice']??'');$sale=null;$items=[];$err='';$msg='';
function load_return_sale(string $invoice): array {if($invoice==='')return [null,[]];$st=db()->prepare('SELECT * FROM sales WHERE invoice_no=?');$st->execute([$invoice]);$sale=$st->fetch();if(!$sale)return [null,[]];$st=db()->prepare('SELECT si.*,p.sku,p.product_name,l.code location_code,ps.serial_barcode,COALESCE((SELECT SUM(sri.quantity) FROM sale_return_items sri WHERE sri.sale_item_id=si.id),0) already_returned FROM sale_items si JOIN products p ON p.id=si.product_id JOIN locations l ON l.id=si.location_id LEFT JOIN product_serials ps ON ps.id=si.serial_id WHERE si.sale_id=?');$st->execute([$sale['id']]);return [$sale,$st->fetchAll()];}
[$sale,$items]=load_return_sale($invoice);
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='return'){csrf_check();if(!$sale)$err='Invoice not found.';elseif($sale['status']==='CANCELLED')$err='Cancelled bill cannot be returned.';else{$saleItemId=(int)($_POST['sale_item_id']??0);$qty=(float)($_POST['quantity']??0);$reason=trim($_POST['reason']??'');$condition=($_POST['condition']??'')==='DAMAGED'?'DAMAGED':'GOOD';try{db()->beginTransaction();$st=db()->prepare('SELECT si.*,COALESCE((SELECT SUM(sri.quantity) FROM sale_return_items sri WHERE sri.sale_item_id=si.id),0) returned_qty FROM sale_items si WHERE si.id=? AND si.sale_id=? FOR UPDATE');$st->execute([$saleItemId,$sale['id']]);$it=$st->fetch();if(!$it||$qty<=0||$qty>((float)$it['quantity']-(float)$it['returned_qty']))throw new Exception('Invalid return quantity.');if($it['serial_id']&&abs($qty-1)>0.0001)throw new Exception('Unique piece return quantity must be 1.');if($reason==='')throw new Exception('Return reason is required.');
 $rn='RET-'.date('YmdHis').'-'.random_int(10,99);db()->prepare('INSERT INTO sale_returns(return_no,sale_id,reason,created_by) VALUES(?,?,?,?)')->execute([$rn,$sale['id'],$reason,current_user()['id']]);$rid=(int)db()->lastInsertId();$ratio=$qty/max(0.000001,(float)$it['quantity']);$refund=round(max(0,((float)$it['taxable_value']+(float)$it['tax_amount'])*$ratio),2);db()->prepare('INSERT INTO sale_return_items(sale_return_id,sale_item_id,quantity,refund_amount) VALUES(?,?,?,?)')->execute([$rid,$saleItemId,$qty,$refund]);$remark=$reason.' · '.$condition;if($condition==='GOOD'){db()->prepare('INSERT INTO inventory_balances(product_id,batch_id,location_id,qty) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE qty=qty+VALUES(qty)')->execute([$it['product_id'],$it['batch_id'],$it['location_id'],$qty]);db()->prepare('UPDATE batches SET qty_available=qty_available+? WHERE id=?')->execute([$qty,$it['batch_id']]);}if($it['serial_id']){$st=db()->prepare("UPDATE product_serials SET status=?,location_id=? WHERE id=? AND status='SOLD'");$st->execute([$condition==='GOOD'?'AVAILABLE':'DAMAGED',$it['location_id'],$it['serial_id']]);if($st->rowCount()!==1)throw new Exception('Unique piece is not in SOLD status.');}db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_in,reference_type,reference_id,unit_rate,remarks,created_by) VALUES('SALE_RETURN',?,?,?,?, 'SALE_RETURN',?,?,?,?)")->execute([$it['product_id'],$it['batch_id'],$it['location_id'],$qty,$rid,$it['unit_price'],$remark,current_user()['id']]);if($condition==='DAMAGED')db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_out,reference_type,reference_id,remarks,created_by) VALUES('DAMAGE',?,?,?,?, 'SALE_RETURN',?,?,?)")->execute([$it['product_id'],$it['batch_id'],$it['location_id'],$qty,$rid,$remark,current_user()['id']]);
 if((int)($sale['customer_id']??0)>0&&(float)$sale['credit_total']>0&&(float)$sale['grand_total']>0){$creditReduction=$refund*((float)$sale['credit_total']/(float)$sale['grand_total']);if($creditReduction>0)db()->prepare("INSERT INTO customer_ledger(customer_id,txn_type,credit,reference_type,reference_id,remarks,created_by) VALUES(?,'RETURN_CREDIT',?,'SALE_RETURN',?,?,?)")->execute([$sale['customer_id'],$creditReduction,$rid,$rn,current_user()['id']]);}
 $st=db()->prepare('SELECT SUM(si.quantity) sold,COALESCE(SUM((SELECT COALESCE(SUM(sri.quantity),0) FROM sale_return_items sri WHERE sri.sale_item_id=si.id)),0) returned FROM sale_items si WHERE si.sale_id=?');$st->execute([$sale['id']]);$tot=$st->fetch();$status=((float)$tot['returned']>=(float)$tot['sold'])?'RETURNED_FULL':'RETURNED_PARTIAL';db()->prepare('UPDATE sales SET status=?, refund_total=(SELECT COALESCE(SUM(sri.refund_amount),0) FROM sale_return_items sri JOIN sale_returns sr ON sr.id=sri.sale_return_id WHERE sr.sale_id=sales.id) WHERE id=?')->execute([$status,$sale['id']]);db()->commit();audit('SALE_RETURN','sale_return',$rid,['invoice'=>$invoice,'qty'=>$qty,'refund'=>$refund,'condition'=>$condition]);publish_event('SALE_RETURN','Sales return posted',$invoice.' · Qty '.number_format($qty,0).' · Refund ₹'.number_format($refund,2),['super_admin'],'sale_return',$rid,null);publish_scoped_event('SALE_RETURN_STOCK_IN','Returned stock received',$invoice.' · Qty '.number_format($qty,0),['manager','godown'],'sale',(int)$sale['id']);$msg=$rn.' completed. Refund amount to process/reconcile: ₹'.number_format($refund,2);
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
 [$sale,$items]=load_return_sale($invoice);
}
page_header('Sales Return · Super Admin');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="get" class="actions"><input name="invoice" value="<?=e($invoice)?>" placeholder="Invoice No."><button class="btn">Find Invoice</button></form><br><?php if($sale):?><div class="panel"><b><?=e($sale['invoice_no'])?></b> · <?=e($sale['created_at'])?> · ₹<?=e(number_format($sale['grand_total'],2))?> · <?=e($sale['status'])?></div><br><table><tr><th>Item</th><th>Unique Barcode</th><th>Sold</th><th>Returned</th><th>Location</th><th>Return</th></tr><?php foreach($items as $i):$remaining=(float)$i['quantity']-(float)$i['already_returned'];?><tr><td><?=e($i['sku'].' · '.$i['product_name'])?></td><td><?=e($i['serial_barcode']?:'Batch Item')?></td><td><?=e($i['quantity'])?></td><td><?=e($i['already_returned'])?></td><td><?=e($i['location_code'])?></td><td><?php if($remaining>0&&$sale['status']!=='CANCELLED'):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="return"><input type="hidden" name="invoice" value="<?=e($invoice)?>"><input type="hidden" name="sale_item_id" value="<?=$i['id']?>"><input type="number" name="quantity" step="0.001" min="0.001" max="<?=$remaining?>" value="<?=$i['serial_id']?1:min(1,$remaining)?>" <?=$i['serial_id']?'readonly':''?> style="width:90px"><input name="reason" required placeholder="Return reason"><select name="condition" style="width:auto"><option value="GOOD">GOOD · restock</option><option value="DAMAGED">DAMAGED · do not restock</option></select><button class="btn">Return</button></form><?php else:?>Complete<?php endif;?></td></tr><?php endforeach;?></table><?php elseif($invoice):?><div class="notice error">Invoice not found.</div><?php endif;?><?php page_footer();
